Hub.CloneLocalPlayerModel = function(self)
	if self.Preview.Model then
		pcall(function()
			self.Preview.Model:Destroy();
		end);
		self.Preview.Model = nil;
	end
	local lp = self.Services.Players.LocalPlayer;
	local char = lp.Character;
	if not char then
		return;
	end
	local clone = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\195\224\52\202\48", "\210\142\143\80\175\92"));
	clone.Name = "PreviewRig";
	local cframeOrigin = char:GetPivot();
	for _, item in ipairs(char:GetChildren()) do
		if (item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\138\225\250\212\173", "\166\217\137\147")) or item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\211\162\124\178\226", "\38\131\195\18\198\145")) or item:IsA("ShirtGraphic") or item:IsA("BodyColors") or item:IsA("CharacterMesh")) then
			pcall(function()
