			if (h and liveH and liveH:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\44\132\168\31\79\116\83\253", "\137\110\229\219\122\31\21\33"))) then
				local rel = cframeOrigin:ToObjectSpace(liveH.CFrame);
				h.CFrame = turnFront * rel;
