		end
	end
	for _, child in ipairs(self.Preview.Model:GetChildren()) do
		if (child:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\46\178\55\119", "\30\122\221\88\27\86\43\68")) or (child:IsA("Model") and (child.Name ~= "PreviewRig"))) then
