		elseif (obj:IsA("Decal") or obj:IsA("Texture")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {Type="Decal",Transparency=obj.Transparency};
			end
			obj.Transparency = 1;
		elseif (obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\151\173\245\191", "\146\209\196\135\218\181\178\192")) or obj:IsA("Sparkles") or obj:IsA("Light")) then
