Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA("BasePart") and p:FindFirstChildOfClass("TouchTransmitter")) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
