				end
			end
			if gunInHand then
				self:ShootGun();
			end
		end
	end);
	self.Services.UserInputService.JumpRequest:Connect(function()
		if self.Config.Toggles.InfiniteJump then
			local hum = self.Services.Players.LocalPlayer.Character and self.Services.Players.LocalPlayer.Character:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\84\4\129\126\198\78\126\35", "\71\28\113\236\31\168\33\23"));
			if hum then
				hum:ChangeState(Enum.HumanoidStateType.Jumping);
			end
		end
	end);
end;
